import React, { useState } from 'react';
import { useLocation, useNavigate, Link } from 'react-router-dom';
// 1. IMPORT SERVICE ĐỂ GỌI API
import { ordersApi } from '../services/api';

const Checkout = () => {
    const location = useLocation();
    const navigate = useNavigate();

    // Nhận dữ liệu từ trang Cart truyền sang
    const { subtotal, discount, cartItems, couponCode } = location.state ||
        { subtotal: 0, discount: 0, cartItems: [], couponCode: null };

    // Các trạng thái xử lý tính phí vận chuyển theo tọa độ thực tế
    const [shippingFee, setShippingFee] = useState(0);
    const [distanceKm, setDistanceKm] = useState(0);
    const [isCalculating, setIsCalculating] = useState(false);
    const [total, setTotal] = useState(subtotal - discount);

    const [formData, setFormData] = useState({
        firstName: '', lastName: '', address: '', town: '', phone: '', email: '', notes: ''
    });
    const [paymentMethod, setPaymentMethod] = useState('Cash On Delivery');

    const handleInputChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    // ===================================================================
    // CÔNG THỨC TOÁN HỌC HAVERSINE: ĐO KHOẢNG CÁCH GIỮA 2 TỌA ĐỘ VỆ TINH
    // ===================================================================
    const calculateDistanceInKm = (lat1, lon1, lat2, lon2) => {
        const R = 6371; // Bán kính Trái Đất tính bằng Km
        const dLat = (lat2 - lat1) * (Math.PI / 180);
        const dLon = (lon2 - lon1) * (Math.PI / 180);
        const a =
            Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
        const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        return R * c;
    };

    // ===================================================================
    // GỌI API OPENSTREETMAP ĐỂ TRA TỌA ĐỘ VÀ TÍNH TIỀN SHIP THEO SỐ KM
    // ===================================================================
    const handleCalculateShipping = async () => {
        if (!formData.address || !formData.town) {
            alert("Ní vui lòng điền Địa chỉ chi tiết và Tỉnh/Thành phố trước khi tính toán phí vận chuyển nhé!");
            return;
        }

        setIsCalculating(true);
        const fullAddress = `${formData.address}, ${formData.town}, Vietnam`;

        try {
            // Sử dụng dịch vụ bản đồ vệ tinh Nominatim miễn phí công khai công nghệ cao
            const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(fullAddress)}`);
            const data = await response.json();

            if (data && data.length > 0) {
                // Tọa độ định vị nhà khách hàng từ chuỗi địa chỉ nhập vào
                const customerLat = parseFloat(data[0].lat);
                const customerLon = parseFloat(data[0].lon);

                // Tọa độ gốc của Cửa hàng Fruitables (Vị trí: 236 Hoàng Quốc Việt, Hà Nội)
                const shopLat = 21.046386;
                const shopLon = 105.795495;

                // Thực hiện đo khoảng cách
                const distance = calculateDistanceInKm(shopLat, shopLon, customerLat, customerLon);
                setDistanceKm(distance);

                // Biểu phí vận chuyển: Phí sàn cố định $1.00 + $0.50 cho mỗi Kilomet di chuyển
                let calculatedFee = 1.00 + (distance * 0.50);
                if (distance < 1) calculatedFee = 1.00; // Nội khu dưới 1km đồng giá $1.00

                setShippingFee(calculatedFee);
                setTotal(subtotal - discount + calculatedFee);

                alert(`Đã xác định vị trí thành công! Khoảng cách giao hàng là ${distance.toFixed(1)} km. Phí ship của ní là: $${calculatedFee.toFixed(2)}`);
            } else {
                alert("Hệ thống định vị không quét ra địa chỉ này. Ní vui lòng kiểm tra lại chính tả tên đường, Quận/Thành phố nha!");
                // Phí dự phòng khi lỗi tìm kiếm
                setShippingFee(5.00);
                setTotal(subtotal - discount + 5.00);
            }
        } catch (error) {
            console.error("Lỗi hệ thống định vị:", error);
            alert("Không thể kết nối đến máy chủ bản đồ. Hệ thống chuyển sang tính phí ship đồng giá cố định $3.00");
            setShippingFee(3.00);
            setTotal(subtotal - discount + 3.00);
        } finally {
            setIsCalculating(false);
        }
    };

    // 2. HÀM PLACE ORDER DÙNG AXIOS (ordersApi)
    const handlePlaceOrder = async (e) => {
        e.preventDefault();

        if (shippingFee === 0) {
            alert("Ní ơi, vui lòng bấm nút 'TÍNH PHÍ VẬN CHUYỂN BẰNG ĐỊNH VỊ' màu vàng trước khi chốt đơn nhé!");
            return;
        }

        if (!formData.firstName || !formData.address || !formData.phone) {
            alert("Ní ơi điền đầy đủ Tên, Địa chỉ với Số điện thoại (có dấu *) giùm tui nha!");
            return;
        }

        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (!currentUserId) {
            alert("Ní chưa đăng nhập mà sao mua hàng được!");
            navigate('/login');
            return;
        }

        const orderData = {
            userId: currentUserId,
            shippingAddress: `${formData.address}, ${formData.town} (Cách shop: ${distanceKm.toFixed(1)}km)`,
            phone: formData.phone,
            orderNotes: formData.notes,
            paymentMethod: paymentMethod,
            subTotal: subtotal,
            shippingFee: shippingFee,
            discountAmount: discount,
            totalAmount: total,
            couponCode: couponCode,
            details: cartItems.map(item => ({
                productId: item.productId || item.id,
                quantity: item.quantity,
                unitPrice: item.productInfo?.price || item.price
            }))
        };

        try {
            // GỌI API QUA SERVICE THAY VÌ FETCH
            await ordersApi.checkout(orderData);

            // Nếu gọi API thành công:
            alert("🎉 Đặt hàng thành công! Đơn hàng đang được chờ xử lý.");
            navigate('/my-orders');
        } catch (error) {
            console.error("Lỗi kết nối API:", error);
            // Lấy thông báo lỗi từ backend
            const errorMsg = error.response?.data || "Lỗi kết nối máy chủ C#!";
            alert(`Có lỗi xảy ra: ${errorMsg}`);
        }
    };

    return (
        <>
            <div className="container-fluid page-header py-5">
                <h1 className="text-center text-white display-6">Thanh Toán</h1>
                <ol className="breadcrumb justify-content-center mb-0">
                    <li className="breadcrumb-item"><Link to="/">Trang chủ</Link></li>
                    <li className="breadcrumb-item"><a href="#">Trang</a></li>
                    <li className="breadcrumb-item active text-white">Thanh toán</li>
                </ol>
            </div>

            <div className="container-fluid py-5">
                <div className="container py-5">
                    <h1 className="mb-4">Thông tin giao hàng</h1>
                    <form onSubmit={handlePlaceOrder}>
                        <div className="row g-5">
                            {/* CỘT BÊN TRÁI */}
                            <div className="col-md-12 col-lg-6 col-xl-7">
                                <div className="row">
                                    <div className="col-md-12 col-lg-6">
                                        <div className="form-item w-100">
                                            <label className="form-label my-3">Họ và tên<sup>*</sup></label>
                                            <input type="text" name="firstName" className="form-control" onChange={handleInputChange} required />
                                        </div>
                                    </div>
                                    <div className="col-md-12 col-lg-6">
                                        <div className="form-item w-100">
                                            <label className="form-label my-3">Tên lót (Tùy chọn)</label>
                                            <input type="text" name="lastName" className="form-control" onChange={handleInputChange} />
                                        </div>
                                    </div>
                                </div>
                                <div className="form-item">
                                    <label className="form-label my-3">Số điện thoại<sup>*</sup></label>
                                    <input type="text" name="phone" className="form-control" onChange={handleInputChange} required />
                                </div>
                                <div className="form-item">
                                    <label className="form-label my-3">Tỉnh / Thành phố / Quận / Huyện <sup>*</sup></label>
                                    <input type="text" name="town" className="form-control border-warning" placeholder="Ví dụ: Cầu Giấy, Hà Nội..." onChange={handleInputChange} required />
                                </div>
                                <div className="form-item">
                                    <label className="form-label my-3">Địa chỉ chi tiết (Tên đường, Số nhà) <sup>*</sup></label>
                                    <input type="text" name="address" className="form-control border-warning" placeholder="Ví dụ: Số 236 đường Hoàng Quốc Việt..." onChange={handleInputChange} required />
                                </div>

                                {/* NÚT KÍCH HOẠT QUÉT ĐỊNH VỊ TÍNH SHIP */}
                                <div className="form-item mt-4">
                                    <button
                                        type="button"
                                        className="btn btn-warning rounded-pill px-4 py-3 fw-bold text-dark w-100"
                                        onClick={handleCalculateShipping}
                                        disabled={isCalculating}
                                    >
                                        <i className="fa fa-map-marker-alt me-2"></i>
                                        {isCalculating ? "Đang quét radar kết nối vệ tinh bản đồ..." : "TÍNH PHÍ VẬN CHUYỂN BẰNG ĐỊNH VỊ"}
                                    </button>
                                    <small className="text-muted d-block text-center mt-2">*Hệ thống tự động đo khoảng cách (km) từ Cửa hàng đến nhà ní để tính phí ship.</small>
                                </div>

                                <div className="form-item">
                                    <label className="form-label my-3">Địa chỉ Email</label>
                                    <input type="email" name="email" className="form-control" onChange={handleInputChange} />
                                </div>
                                <div className="form-item mt-3">
                                    <textarea name="notes" className="form-control" rows="5" placeholder="Ghi chú đơn hàng (Tùy chọn)" onChange={handleInputChange}></textarea>
                                </div>

                                <div className="form-item mt-4">
                                    <label className="form-label mb-2 fw-bold">Phương thức thanh toán:</label>
                                    <select className="form-select" value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}>
                                        <option value="Cash On Delivery">Thanh toán khi nhận hàng (COD)</option>
                                        <option value="Bank Transfer">Chuyển khoản qua ngân hàng</option>
                                    </select>
                                </div>
                            </div>

                            {/* CỘT BÊN PHẢI (HÓA ĐƠN CHI TIẾT) */}
                            <div className="col-md-12 col-lg-6 col-xl-5">
                                <div className="table-responsive bg-light rounded p-5">
                                    <h2 className="display-6 mb-4">Hóa Đơn Của Bạn</h2>
                                    <table className="table">
                                        <thead>
                                            <tr>
                                                <th scope="col">Sản phẩm</th>
                                                <th scope="col">Tên</th>
                                                <th scope="col">Thành tiền</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {cartItems.map((item, index) => {
                                                const finalPrice = item.discountPrice || item.price;
                                                return (
                                                    <tr key={index}>
                                                        <td><img src={item.imageUrl || '/img/avatar.jpg'} style={{ width: '60px', height: '60px', objectFit: 'cover', borderRadius: '50%' }} alt="" /></td>
                                                        <td>{item.name} <span className="text-muted fw-bold">x{item.quantity}</span></td>
                                                        <td>${(finalPrice * item.quantity).toFixed(2)}</td>
                                                    </tr>
                                                )
                                            })}
                                            <tr>
                                                <td><strong>Tổng tiền hàng:</strong></td>
                                                <td></td>
                                                <td><strong>${subtotal.toFixed(2)}</strong></td>
                                            </tr>

                                            {discount > 0 && (
                                                <tr className="text-success">
                                                    <td><strong>Đã giảm giá:</strong></td>
                                                    <td></td>
                                                    <td><strong>-${discount.toFixed(2)}</strong></td>
                                                </tr>
                                            )}

                                            {/* HIỂN THỊ KHOẢNG CÁCH VÀ PHÍ SHIP */}
                                            <tr>
                                                <td>
                                                    <strong>Phí vận chuyển:</strong><br />
                                                    {shippingFee === 0 ? (
                                                        <small className="text-danger fw-bold">*Bấm nút tính phí bên trái</small>
                                                    ) : (
                                                        <small className="text-success fw-bold">Khoảng cách: {distanceKm.toFixed(1)} km</small>
                                                    )}
                                                </td>
                                                <td></td>
                                                <td>
                                                    <strong className={shippingFee === 0 ? "text-danger" : "text-dark"}>
                                                        {shippingFee === 0 ? "Chưa tính" : `$${shippingFee.toFixed(2)}`}
                                                    </strong>
                                                </td>
                                            </tr>

                                            <tr className="border-top border-dark border-2 bg-white">
                                                <td><strong className="text-primary fs-5">TỔNG CỘNG:</strong></td>
                                                <td></td>
                                                <td><strong className="text-danger fs-5">${total.toFixed(2)}</strong></td>
                                            </tr>
                                        </tbody>
                                    </table>
                                    <button
                                        type="submit"
                                        className="btn border-secondary bg-primary text-white py-3 px-4 text-uppercase w-100 fw-bold mt-4"
                                        disabled={shippingFee === 0}
                                    >
                                        XÁC NHẬN ĐẶT HÀNG
                                    </button>
                                </div>
                            </div>
                        </div>
                    </form>
                </div>
            </div>
        </>
    );
};

export default Checkout;
